def bfs_with_distances(graph, start):
    # Track minimum distance to each node
    distance = {start: 0}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        current_dist = distance[node]

        for neighbor in graph.get(node, []):
            if neighbor not in distance:
                distance[neighbor] = current_dist + 1
                queue.append(neighbor)

    return distance

distances = bfs_with_distances(graph, '8f14e45fce')
print("Distances from 8f14e45fce:")
for d in range(5):
    nodes_at_d = [n for n, dist in sorted(distances.items()) if dist == d]
    print(f"Depth {d}: {nodes_at_d}")

print(f"\nAll reachable nodes: {len(distances)}")
print(f"Max depth reached: {max(distances.values())}")

